export const studentHouseMap = {};
export const classStudentHouseMap = {};

// Helper to normalize class names for flexible matching (e.g. "6 B" vs "Class 6 B")
const normalizeClass = (cls) => {
  if (!cls) return '';
  return cls.toLowerCase()
    .replace(/^classs*/i, '')
    .replace(/s+/g, ' ')
    .trim();
};

const normalizeName = (name) => {
  if (!name) return '';
  return name.toLowerCase().trim().replace(/\s+/g, ' ');
};

studentHouseRecords.forEach(([cls, name, house]) => {
  const normClass = normalizeClass(cls);
  const normName = normalizeName(name);
  
  classStudentHouseMap[`${normClass}::${normName}`] = house;
  // Also store default by name (first occurrence or fallback)
  if (!studentHouseMap[normName]) {
    studentHouseMap[normName] = house;
  }
});

export const getStudentHouse = (name, className = '') => {
  if (!name) return null;
  const normName = normalizeName(name);
  const normClass = normalizeClass(className);

  // 1. Check exact Class + Student Name match
  if (normClass && classStudentHouseMap[`${normClass}::${normName}`]) {
    return classStudentHouseMap[`${normClass}::${normName}`];
  }

  // 2. Direct student name match
  if (studentHouseMap[normName]) {
    return studentHouseMap[normName];
  }

  // 3. Permutation/word matching (handles "Gurung Aaradhna" vs "Aaradhna Gurung")
  const targetWords = normName.split(' ').sort();
  for (const [cls, recName, house] of studentHouseRecords) {
    if (normClass && normalizeClass(cls) !== normClass) continue;
    const recWords = recName.split(' ').sort();
    if (targetWords.length === recWords.length && targetWords.every((w, i) => w === recWords[i])) {
      return house;
    }
  }

  // Fallback word matching across entire school
  for (const [key, house] of Object.entries(studentHouseMap)) {
    const keyWords = key.split(' ').sort();
    if (targetWords.length === keyWords.length && targetWords.every((w, i) => w === keyWords[i])) {
      return house;
    }
  }

  return null;
};

export const getHouseBadgeColor = (house) => {
  switch (house?.toLowerCase()?.trim()) {
    case 'topaz':
      return 'bg-amber-500/15 text-amber-400 border-amber-500/30';
    case 'turquoise':
      return 'bg-cyan-500/15 text-cyan-400 border-cyan-500/30';
    case 'onyx':
      return 'bg-slate-700/60 text-slate-200 border-slate-600';
    case 'garnet':
      return 'bg-rose-500/15 text-rose-400 border-rose-500/30';
    default:
      return 'bg-slate-800 text-slate-300 border-slate-700';
  }
};
